void Solver::bump_var(int var, double coeff) {
    double bump_amount = var_inc * coeff * (1.0 + (double)level[var] / (double)pos_in_trail.size());
    if ((activity[var] += bump_amount) > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
